    try std.testing.expectError(error.UnqualifiedCompactionArtifact, zero_binary.validate(identity, .cumulative256_exact_cycle_v1, @splat(5), @splat(6)));

    try std.testing.expect(!grant.usesExactLocalWindowCapacity());
