                if (page_size > 0 and seq_len > page_size) {
                    const maybe_hit = cache.attachLongestPrefix(
                        config.prompt_cache_key.?,
                        token_ids[0..seq_len],
                        seq_len - page_size,
                    ) catch |err| blk: {
                        std.log.warn("prompt cache lookup failed; continuing without reuse: {s}", .{@errorName(err)});
                        break :blk null;
                    };
