                            decode_state.seedAttachedPrefix(hit.sequence_id, hit.token_count) catch |err| {
                                cache.releaseAttachedPrefix(hit);
                                std.log.warn("prompt cache seed failed; continuing without reuse: {s}", .{@errorName(err)});
                                break :blk false;
                            };
                            break :blk true;
